contract InvMutTest {
    C c;
    constructor(C _c) payable { c = _c; }

    function run(bytes32 g1, bytes32 g2, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 * amount);

        // initial lock-in succeeds
        c.lockInGuess{value: amount}(g1);

        // second lock-in while guess is pending must revert
        bool locked;
        try c.lockInGuess{value: amount}(g2) { locked = false; } catch { locked = true; }

        // settle (needs to be a top-level call)
        c.settle();

        // after settle, locking in a new guess must succeed
        bool relocked = true;
        try c.lockInGuess{value: amount}(g2) { relocked = true; } catch { relocked = false; }

        assert(locked && relocked);
    }

    receive() external payable {}
}

