contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g) public payable {
        // settle before any lock-in must revert
        bool r0;
        try c.settle() { r0 = false; } catch { r0 = true; }
        // lock in a guess (needs 1 ether from the test contract)
        uint amt = 1 ether;
        require(address(this).balance >= amt);
        c.lockInGuess{value: amt}(g);
        // settle before the target block must revert
        bool r1;
        try c.settle() { r1 = false; } catch { r1 = true; }
        // advance one block so block.number > guesses[msg.sender].block
        bool advanced;
        try c.settle() { advanced = false; } catch { advanced = true; }
        // advance one more block; now settle should succeed and clear the guess
        bool r2;
        if (advanced) {
            try c.settle() { r2 = false; } catch { r2 = true; }
        } else {
            r2 = false;
        }
        // after a successful settle, the guess is cleared: settle must revert again
        bool r3;
        try c.settle() { r3 = false; } catch { r3 = true; }
        assert(r0 && r1 && !r3);
    }
    receive() external payable {}
}

